// Import HTML is escaped and generated by notion.ts. Adjacent figures (with
// optional empty Notion paragraphs) form a gallery, even across column blocks.
// Apply at presentation time so existing saved snapshots also get the layout.
export function imageLayout(html: string, zoom = false): string {
  if (zoom)
    html = html.replace(/<img\b[^>]*>/g, (img) => {
      const src = img.match(/\bsrc="([^"]*)"/)?.[1];
      const alt = img.match(/\balt="([^"]*)"/)?.[1] || "";
      return src
        ? `<a href="${src}" data-fancybox="post" data-caption="${alt}">${img}</a>`
        : img;
    });
  const figure = String.raw`<figure\b[^>]*>[\s\S]*?<\/figure>`;
  const gap = String.raw`(?:\s|<p\b[^>]*>(?:\s|<br\s*\/?>)*<\/p>)*`;
  return html.replace(
    new RegExp(`${figure}(?:${gap}${figure})+`, "g"),
    (group) => {
      const images = group.match(new RegExp(figure, "g"))!;
      const columns = images.length === 3 ? 3 : 2;
      const rows: string[] = [];
      for (let i = 0; i < images.length; i += columns) {
        rows.push(
          `<tr>${images
            .slice(i, i + columns)
            .map(
              (image) =>
                `<td class="notion-gallery-cell" width="${100 / columns}%" style="vertical-align:top;padding:12px">${image}</td>`,
            )
            .join("")}</tr>`,
        );
      }
      return `<table role="presentation" class="notion-gallery notion-gallery-${columns}" style="width:100%;table-layout:fixed;border-collapse:collapse;margin:24px 0"><tbody>${rows.join("")}</tbody></table>`;
    },
  );
}
